window.MATH_TOPICS = [
{id:"suite-limite",title:"Limite d'une suite",level:"L1",category:"Analyse",desc:"Comprendre la convergence et savoir rédiger avec ε et N.",duration:"12 min",definition:"Une suite réelle (uₙ) converge vers ℓ si, à partir d'un certain rang, ses termes sont aussi proches que l'on veut de ℓ.",formula:"∀ ε > 0, ∃ N ∈ ℕ, ∀ n ≥ N : |uₙ − ℓ| < ε",proof:"Pour démontrer que uₙ → ℓ, on fixe ε > 0. On cherche un rang N dépendant de ε tel que, pour tout n ≥ N, l'inégalité |uₙ − ℓ| < ε soit vérifiée.",points:["Le rang N dépend de ε.","La propriété doit être vraie pour tout n ≥ N.","La limite, si elle existe, est unique."],example:"Pour uₙ = 1/n, on veut 1/n < ε. Il suffit de choisir N > 1/ε."},
{id:"continuite",title:"Continuité en un point",level:"L1",category:"Analyse",desc:"Relier limite, valeur de la fonction et comportement local.",duration:"10 min",definition:"f est continue en a si limₓ→ₐ f(x) = f(a).",formula:"∀ ε > 0, ∃ δ > 0 : |x − a| < δ ⇒ |f(x) − f(a)| < ε",proof:"On fixe ε > 0. La continuité garantit l'existence de δ > 0 tel que tout x de l'ensemble de définition vérifiant |x−a| < δ vérifie aussi |f(x)−f(a)| < ε.",points:["La continuité est une propriété locale.","Une fonction dérivable en a est continue en a.","La réciproque est fausse en général."],example:"La fonction x ↦ x² est continue sur ℝ, car les polynômes sont continus."},
{id:"derivee",title:"Dérivée en un point",level:"L1",category:"Analyse",desc:"Interpréter le nombre dérivé comme pente de la tangente.",duration:"12 min",definition:"f est dérivable en a si le taux d'accroissement admet une limite finie lorsque h tend vers 0.",formula:"f′(a) = limₕ→₀ [f(a+h) − f(a)] / h",proof:"On étudie la limite du quotient de différences. Si elle existe et est finie, sa valeur est le nombre dérivé en a.",points:["Le nombre dérivé est la pente de la tangente.","Dérivable implique continue.","La dérivée décrit une variation locale."],example:"Pour f(x)=x², f′(a)=limₕ→₀(2ah+h²)/h=2a."},
{id:"theoreme-valeurs-intermediaires",title:"Théorème des valeurs intermédiaires",level:"L1",category:"Analyse",desc:"Garantir l'existence d'une solution à une équation.",duration:"8 min",definition:"Si f est continue sur [a,b], alors toute valeur comprise entre f(a) et f(b) est atteinte par f.",formula:"λ ∈ [min(f(a),f(b)), max(f(a),f(b))] ⇒ ∃ c ∈ [a,b] : f(c)=λ",proof:"C'est une conséquence de la continuité sur un intervalle : l'image d'un intervalle par une fonction continue est un intervalle.",points:["Le TVI donne une existence, pas forcément une unicité.","La continuité sur tout le segment est essentielle.","La stricte monotonie peut donner l'unicité."],example:"Si f est continue, f(0)<0 et f(1)>0, alors f s'annule au moins une fois sur [0,1]."},
{id:"integrale",title:"Intégrale sur un segment",level:"L1",category:"Analyse",desc:"Lire l'intégrale comme accumulation et aire algébrique.",duration:"10 min",definition:"Pour une fonction continue f sur [a,b], l'intégrale ∫ₐᵇ f(x)dx représente l'aire algébrique sous la courbe.",formula:"∫ₐᵇ f(x) dx = F(b) − F(a), où F′ = f",proof:"Le théorème fondamental de l'analyse relie l'intégration à la recherche d'une primitive.",points:["L'intégrale peut être négative si f est négative.","L'intégrale est additive par rapport aux intervalles.","Si f ≥ 0, l'intégrale est positive."],example:"∫₀¹ 2x dx = [x²]₀¹ = 1."},
{id:"series",title:"Séries numériques",level:"L2",category:"Analyse",desc:"Étudier la convergence d'une somme infinie.",duration:"14 min",definition:"La série ∑uₙ converge si la suite de ses sommes partielles Sₙ = ∑ₖ₌₀ⁿuₖ converge.",formula:"Sₙ = u₀ + u₁ + ⋯ + uₙ",proof:"On étudie la convergence de la suite (Sₙ). Une condition nécessaire est uₙ → 0, mais elle n'est pas suffisante.",points:["Si ∑uₙ converge, alors uₙ → 0.","La série harmonique ∑1/n diverge.","Les séries géométriques se traitent avec une formule explicite."],example:"∑ₙ₌₀∞ qⁿ converge si |q|<1 et sa somme vaut 1/(1−q)."},
{id:"uniforme",title:"Convergence uniforme",level:"L2",category:"Analyse",desc:"Comprendre une convergence contrôlée uniformément sur un ensemble.",duration:"13 min",definition:"fₙ converge uniformément vers f sur E si l'écart maximal entre fₙ et f tend vers 0.",formula:"supₓ∈E |fₙ(x) − f(x)| → 0",proof:"Pour tout ε > 0, il existe N tel que pour tout n ≥ N et tout x ∈ E, |fₙ(x)−f(x)| < ε. Le rang N ne dépend pas de x.",points:["Le rang N est indépendant du point x.","La convergence uniforme implique la convergence simple.","Elle permet, sous hypothèses, de transmettre la continuité à la limite."],example:"fₙ(x)=x/n converge uniformément vers 0 sur [0,1], mais pas sur ℝ."},
{id:"espaces-vectoriels",title:"Espaces vectoriels",level:"L1",category:"Algèbre",desc:"Maîtriser les axiomes et reconnaître les sous-espaces.",duration:"12 min",definition:"Un espace vectoriel sur un corps K est un ensemble muni d'une addition et d'une multiplication par les scalaires vérifiant les axiomes usuels.",formula:"u,v ∈ E, λ,μ ∈ K ⇒ λu + μv ∈ E",proof:"Pour montrer qu'une partie F de E est un sous-espace vectoriel, on vérifie qu'elle est non vide et stable par combinaison linéaire.",points:["Le vecteur nul appartient à tout sous-espace.","La stabilité par combinaison linéaire suffit avec la non-vacuité.","L'intersection de sous-espaces est un sous-espace."],example:"Dans ℝ², une droite passant par l'origine est un sous-espace vectoriel."},
{id:"familles-liberes",title:"Familles libres et génératrices",level:"L1",category:"Algèbre",desc:"Comprendre les notions qui conduisent aux bases.",duration:"10 min",definition:"Une famille (e₁,…,eₚ) est libre si la seule combinaison linéaire nulle est celle dont tous les coefficients sont nuls.",formula:"λ₁e₁ + ⋯ + λₚeₚ = 0 ⇒ λ₁ = ⋯ = λₚ = 0",proof:"Pour tester la liberté, on écrit une combinaison linéaire nulle et on résout le système obtenu.",points:["Une famille contenant le vecteur nul est liée.","Une famille est génératrice si tout vecteur s'écrit comme combinaison linéaire.","Une base est libre et génératrice."],example:"Les vecteurs (1,0) et (0,1) forment une base de ℝ²."},
{id:"applications-lineaires",title:"Applications linéaires",level:"L1",category:"Algèbre",desc:"Étudier les transformations qui préservent les combinaisons linéaires.",duration:"13 min",definition:"Une application f:E→F est linéaire si elle préserve l'addition et la multiplication par un scalaire.",formula:"f(λu + μv) = λf(u) + μf(v)",proof:"Il suffit de vérifier séparément f(u+v)=f(u)+f(v) et f(λu)=λf(u).",points:["f(0)=0.","L'image d'un sous-espace est un sous-espace.","Le noyau est un sous-espace de l'espace de départ."],example:"La rotation vectorielle de centre O et d'angle fixé est linéaire."},
{id:"diagonalisation",title:"Diagonalisation",level:"L2",category:"Algèbre",desc:"Changer de base pour représenter un endomorphisme par une matrice diagonale.",duration:"15 min",definition:"Un endomorphisme est diagonalisable s'il existe une base formée de vecteurs propres.",formula:"A = P D P⁻¹",proof:"On recherche les valeurs propres avec det(A−λI)=0, puis les espaces propres. On vérifie que la somme de leurs dimensions vaut la dimension de l'espace.",points:["Les colonnes de P sont des vecteurs propres indépendants.","D contient les valeurs propres dans le même ordre.","Une matrice ayant n valeurs propres distinctes est diagonalisable."],example:"Une matrice réelle symétrique est diagonalisable dans une base orthonormée."},
{id:"compacite",title:"Compacité dans ℝⁿ",level:"MP",category:"Analyse",desc:"Relier compacité, suites et propriétés d'existence.",duration:"12 min",definition:"Dans ℝⁿ, un ensemble est compact si et seulement s'il est fermé et borné.",formula:"K compact ⇔ K fermé et borné",proof:"Le théorème de Bolzano-Weierstrass assure que toute suite d'un compact admet une sous-suite convergente dans cet ensemble.",points:["Une fonction continue sur un compact est bornée et atteint ses bornes.","Toute suite d'un compact admet une valeur d'adhérence dans le compact.","En dimension finie, fermé et borné équivaut à compact."],example:"Le segment [0,1] est compact dans ℝ."}
,{id:"schmidt",title:"Procédé de Gram-Schmidt en dimension 2",level:"L2",category:"Algèbre",desc:"Construire une base orthonormée à partir de deux vecteurs libres.",duration:"15 min",definition:"À partir de deux vecteurs libres v₁,v₂ d'un espace euclidien du plan, on pose u₁=v₁ puis on retire à v₂ sa projection orthogonale sur u₁ : w₂=v₂−projᵤ₁(v₂). On normalise ensuite u₁ et w₂.",formula:"e₁=v₁/‖v₁‖ ; projₑ₁(v₂)=⟨v₂,e₁⟩e₁ ; w₂=v₂−projₑ₁(v₂) ; e₂=w₂/‖w₂‖",proof:"La construction garantit ⟨w₂,u₁⟩=0. Comme v₁,v₂ sont libres, w₂ n'est pas nul. Les vecteurs normalisés forment donc une base orthonormée.",points:["On ne peut pas appliquer le procédé si v₁ et v₂ sont colinéaires.","La projection est parallèle à u₁.","Le résidu w₂ est orthogonal à u₁."],example:"Avec v₁=(1,0) et v₂=(1,1), la projection vaut (1,0), puis le résidu vaut (0,1). La base orthonormée est déjà (1,0),(0,1)."},
{id:"fourier",title:"Séries de Fourier",level:"L2",category:"Analyse",desc:"Décomposer une fonction périodique en harmoniques sinusoïdales.",duration:"16 min",definition:"Une série de Fourier représente une fonction périodique comme une somme de sinus et cosinus de fréquences multiples de la fréquence fondamentale.",formula:"f(x) ~ a₀/2 + Σₙ≥1 (aₙ cos(nx)+bₙ sin(nx))",proof:"Les coefficients sont obtenus par projection orthogonale sur les fonctions trigonométriques dans un espace de fonctions muni du produit scalaire intégral.",points:["La convergence dépend de la régularité de la fonction.","Aux points de saut, la série converge classiquement vers la demi-somme des limites latérales.","Les harmoniques ajoutées affinent l'approximation."],example:"Une onde carrée peut être approchée par une somme de sinus impairs : sin(x)+sin(3x)/3+sin(5x)/5+…"},
{id:"developpements-limites",title:"Développements limités des fonctions usuelles",level:"L1",category:"Analyse",desc:"Voir comment les polynômes locaux approchent une fonction près d'un point.",duration:"18 min",definition:"Un développement limité à l'ordre n en 0 écrit f(x) comme un polynôme de degré au plus n plus un reste négligeable devant xⁿ.",formula:"f(x)=a₀+a₁x+…+aₙxⁿ+o(xⁿ) quand x→0",proof:"Les coefficients sont déterminés par les dérivées en 0 lorsque f est suffisamment dérivable. L'animation superpose les polynômes successifs à la fonction.",points:["L'approximation est locale, près du point de développement.","Augmenter l'ordre améliore généralement l'approximation près de 0.","Le reste o(xⁿ) doit être interprété lorsque x tend vers 0."],example:"eˣ=1+x+x²/2!+x³/3!+…+xⁿ/n!+o(xⁿ)."},
{id:"determinant",title:"Déterminant et aire orientée",level:"L1",category:"Algèbre",desc:"Visualiser le facteur d'aire et le signe du déterminant en dimension 2.",duration:"14 min",definition:"Le déterminant de deux vecteurs du plan mesure l'aire orientée du parallélogramme qu'ils engendrent. Pour une matrice 2×2, il mesure le facteur d'aire de la transformation linéaire.",formula:"det([[a,b],[c,d]]) = ad−bc",proof:"L'image du carré unité par la matrice est un parallélogramme dont l'aire vaut |det(A)|. Le signe indique si l'orientation est conservée ou inversée.",points:["det(A)=0 signifie que la transformation écrase le plan sur une droite ou un point.","|det(A)| est le facteur de multiplication des aires.","Un déterminant négatif inverse l'orientation."],example:"La matrice diag(2,3) multiplie les aires par 6."},
{id:"fonctions-deux-variables",title:"Fonctions de deux variables",level:"L2",category:"Analyse",desc:"Explorer une surface z=f(x,y), ses coupes et ses lignes de niveau.",duration:"17 min",definition:"Une fonction de deux variables associe à chaque couple (x,y) de son domaine un réel f(x,y), représentable comme une surface dans l'espace.",formula:"z=f(x,y) ; ∇f=(∂f/∂x, ∂f/∂y)",proof:"Les dérivées partielles décrivent les variations dans les directions des axes. Les lignes de niveau sont les courbes f(x,y)=c.",points:["Une coupe fixe x ou y donne une fonction d'une variable.","Les lignes de niveau relient les points de même altitude.","Le gradient indique la direction de plus forte croissance."],example:"f(x,y)=x²+y² est un paraboloïde dont les lignes de niveau sont des cercles."},
{id:"somme-directe",title:"Somme directe de sous-espaces",level:"L1",category:"Algèbre",desc:"Voir comment deux sous-espaces se complètent sans recouvrement non trivial.",duration:"13 min",definition:"E est la somme directe de F et G si chaque vecteur de E s'écrit de manière unique comme somme d'un élément de F et d'un élément de G.",formula:"E=F⊕G ⇔ E=F+G et F∩G={0}",proof:"L'intersection réduite au vecteur nul garantit l'unicité de la décomposition. La somme égale à E garantit son existence.",points:["La somme directe impose F∩G={0}.","En dimension finie, dim(F⊕G)=dim(F)+dim(G).", "La décomposition est unique."],example:"Dans ℝ², l'axe horizontal et l'axe vertical sont en somme directe et leur somme vaut ℝ²."},
{id:"groupes-anneaux-corps",title:"Groupes, anneaux et corps",level:"L2",category:"Algèbre",desc:"Distinguer les structures algébriques et leurs opérations.",duration:"18 min",definition:"Un groupe est un ensemble muni d'une loi associative, d'un neutre et d'inverses (et commutative s'il est abélien). Un anneau possède une addition abélienne et une multiplication associative distributive. Un corps commutatif est un anneau où tout élément non nul est inversible pour la multiplication.",formula:"Groupe → une loi ; Anneau → + et × ; Corps → +, × et division par tout non-zéro",proof:"On vérifie les axiomes opération par opération : associativité, neutres, inverses et distributivité.",points:["Dans un corps, 0 n'a pas d'inverse multiplicatif.","La multiplication d'un anneau n'est pas nécessairement commutative.","ℚ, ℝ et ℂ sont des corps commutatifs."],example:"(ℤ,+) est un groupe abélien ; ℤ est un anneau ; ℚ est un corps."},
{id:"hyperplan",title:"Hyperplans vectoriels",level:"L1",category:"Algèbre",desc:"Visualiser un sous-espace de codimension 1 comme noyau d'une forme linéaire.",duration:"12 min",definition:"Dans un espace vectoriel de dimension finie, un hyperplan est un sous-espace de dimension dim(E)−1. Il est le noyau d'une forme linéaire non nulle.",formula:"H=Ker(φ), φ:E→K linéaire non nulle",proof:"Le théorème du rang donne dim(Ker φ)=dim(E)−1 puisque l'image d'une forme linéaire non nulle est de dimension 1.",points:["Dans ℝ², un hyperplan est une droite passant par l'origine.","Dans ℝ³, un hyperplan est un plan passant par l'origine.","Un hyperplan vectoriel passe toujours par 0."],example:"Dans ℝ³, H={(x,y,z) | x+2y−z=0} est un plan vectoriel."},
{id:"integrales-generalisees",title:"Intégrales généralisées",level:"L2",category:"Analyse",desc:"Étudier les intégrales sur un intervalle non borné ou avec une singularité.",duration:"16 min",definition:"Une intégrale généralisée est définie comme une limite d'intégrales sur des segments lorsque la borne est infinie ou que l'intégrande présente une singularité.",formula:"∫ₐ⁺∞ f = limᵦ→⁺∞ ∫ₐᵇ f ; convergence si la limite est finie",proof:"On tronque l'intervalle, on calcule l'intégrale ordinaire, puis on étudie la limite. Pour une singularité en c, on traite séparément les deux côtés.",points:["La convergence doit être vérifiée à chaque borne problématique.","Une valeur principale ne remplace pas la convergence usuelle.","Les critères de comparaison sont souvent utiles."],example:"∫₁⁺∞ 1/xᵖ dx converge si et seulement si p>1."},
{id:"ev-normes",title:"Espaces vectoriels normés",level:"L2",category:"Algèbre",desc:"Mesurer la taille des vecteurs et définir la convergence dans un espace vectoriel.",duration:"15 min",definition:"Une norme associe à chaque vecteur un réel positif, nulle seulement au vecteur nul, homogène et vérifiant l'inégalité triangulaire.",formula:"‖x‖≥0 ; ‖x‖=0⇔x=0 ; ‖λx‖=|λ|‖x‖ ; ‖x+y‖≤‖x‖+‖y‖",proof:"La norme définit une distance d(x,y)=‖x−y‖, qui permet de parler de convergence, de suites de Cauchy et d'ouverts.",points:["Une norme induit une distance.","En dimension finie, toutes les normes sont équivalentes.","La convergence dépend de la norme en dimension infinie."],example:"Dans ℝ², ‖(x,y)‖₂=√(x²+y²) est la norme euclidienne."},
{id:"legendre",title:"Polynômes de Legendre",level:"MP",category:"Analyse",desc:"Découvrir une famille de polynômes orthogonaux sur [−1,1].",duration:"16 min",definition:"Les polynômes de Legendre sont orthogonaux pour le produit scalaire intégral ⟨P,Q⟩=∫₋₁¹P(x)Q(x)dx.",formula:"P₀=1 ; P₁=x ; P₂=(3x²−1)/2 ; Pₙ(1)=1",proof:"Ils peuvent être construits par la formule de Rodrigues et sont orthogonaux deux à deux sur [−1,1].",points:["Pₙ est de degré n.","Pₙ a la même parité que n.","L'orthogonalité est relative au produit scalaire intégral."],example:"P₀ et P₁ sont orthogonaux car ∫₋₁¹ x dx=0."}
,{id:"iaf",title:"Inégalité des accroissements finis (IAF)",level:"L1",category:"Analyse",desc:"Contrôler les variations d'une fonction grâce à sa dérivée.",duration:"12 min",definition:"Si f est continue sur [a,b], dérivable sur ]a,b[ et s'il existe M≥0 tel que |f'(x)|≤M, alors |f(b)−f(a)|≤M|b−a|.",formula:"\\(|f(b)-f(a)|\\le M|b-a|\\)",proof:"Le théorème des accroissements finis donne un c∈]a,b[ tel que f(b)−f(a)=f'(c)(b−a). On prend les valeurs absolues et on utilise |f'(c)|≤M.",points:["Les hypothèses de continuité sur [a,b] et de dérivabilité sur ]a,b[ sont essentielles.","Si |f'|≤M, f est M-lipschitzienne.","Si f'=0 sur un intervalle, f y est constante."],example:"Pour f(x)=sin x, |f'(x)|=|cos x|≤1, donc |sin b−sin a|≤|b−a|."}
,{id:"rolle",title:"Théorème de Rolle",level:"L1",category:"Analyse",desc:"Garantir l'existence d'un point où la dérivée s'annule.",duration:"9 min",definition:"Si f est continue sur [a,b], dérivable sur ]a,b[ et f(a)=f(b), alors il existe c∈]a,b[ tel que f'(c)=0.",formula:"\\(f(a)=f(b)\\Rightarrow\\exists c\\in]a,b[:f'(c)=0\\)",proof:"La fonction atteint ses extrema sur le segment. Si elle n'est pas constante, un extremum est atteint à l'intérieur, où la dérivée s'annule.",points:["La continuité sur le segment garantit les extrema.","L'égalité des valeurs aux bornes est essentielle.","Le TAF généralise Rolle."],example:"Pour f(x)=x²−1 sur [−1,1], f(−1)=f(1)=0 et f'(0)=0."}
,{id:"groupes",title:"Groupes",level:"L1",category:"Algèbre",desc:"Loi associative, élément neutre et inverses.",duration:"12 min",definition:"Un groupe (G,⋆) est un ensemble muni d'une loi associative, d'un élément neutre et tel que tout élément admet un inverse. Il est abélien si la loi est commutative.",formula:"\\((a\\star b)\\star c=a\\star(b\\star c),\\quad a\\star a^{-1}=e\\)",proof:"Vérifier la stabilité, l'associativité, l'existence d'un neutre et l'existence des inverses.",points:["Le neutre est unique.","L'inverse de chaque élément est unique.","Un groupe n'est pas nécessairement commutatif."],example:"(ℤ,+) est un groupe abélien : le neutre est 0 et l'inverse de n est −n."}
,{id:"anneaux",title:"Anneaux",level:"L1",category:"Algèbre",desc:"Deux lois compatibles par distributivité.",duration:"13 min",definition:"Un anneau (A,+,×) est un groupe abélien pour l'addition, muni d'une multiplication associative distributive sur l'addition. On précise si l'anneau est unitaire et/ou commutatif.",formula:"\\(a(b+c)=ab+ac,\\quad(a+b)c=ac+bc\\)",proof:"Vérifier la structure de groupe abélien pour +, puis l'associativité de × et les distributivités.",points:["La multiplication n'est pas toujours commutative.","Dans un anneau unitaire, 1 est neutre multiplicatif.","ℤ est un anneau commutatif unitaire."],example:"ℤ est un anneau, mais 2 n'y est pas inversible pour la multiplication."}
,{id:"corps",title:"Corps",level:"L1",category:"Algèbre",desc:"Structures où tout élément non nul est inversible.",duration:"12 min",definition:"Un corps commutatif est un anneau commutatif unitaire dans lequel tout élément non nul possède un inverse multiplicatif.",formula:"\\(\\forall a\\in K\\setminus\\{0\\},\\exists a^{-1}\\in K:aa^{-1}=1\\)",proof:"On reprend les axiomes d'un anneau commutatif unitaire et on ajoute l'inversibilité multiplicative de chaque élément non nul.",points:["On ne divise jamais par zéro.","ℚ, ℝ et ℂ sont des corps commutatifs.","ℤ n'est pas un corps car 2 n'a pas d'inverse dans ℤ."],example:"Dans ℚ, l'inverse de 3/5 est 5/3."}
,{id:"prehilbert",title:"Espaces préhilbertiens et orthogonalité",level:"L1",category:"Algèbre",desc:"Produit scalaire, norme associée, orthogonalité et Pythagore.",duration:"16 min",definition:"Un espace préhilbertien réel est un espace vectoriel réel muni d'un produit scalaire : une forme bilinéaire, symétrique et définie positive. Il induit la norme ‖x‖=√⟨x,x⟩.",formula:"\\(\\|x\\|=\\sqrt{\\langle x,x\\rangle}\\)",proof:"Si x et y sont orthogonaux, leur produit scalaire est nul ; développer ‖x+y‖² donne l'identité de Pythagore.",points:["Cauchy-Schwarz : |⟨x,y⟩|≤‖x‖‖y‖.","Orthogonalité : ⟨x,y⟩=0.","Pythagore : si x⊥y, ‖x+y‖²=‖x‖²+‖y‖².","Gram-Schmidt construit une famille orthogonale puis orthonormée."],example:"Dans ℝ² usuel, (1,0) et (0,2) sont orthogonaux et ‖(1,2)‖²=1+4=5."}

];


window.MATH_COURSE_DETAILS = {
 "schmidt":[
  {title:"1. Hypothèses et objectif",body:"On travaille dans un espace préhilbertien réel avec deux vecteurs v₁,v₂ linéairement indépendants. On veut construire une base orthonormée du même plan. L'indépendance garantit que le résidu obtenu à la deuxième étape ne sera pas nul."},
  {title:"2. Normaliser le premier vecteur",body:"On pose e₁=v₁/‖v₁‖. On a alors ‖e₁‖=1. Cette normalisation est importante : la formule de projection devient particulièrement simple.",formula:"e₁=v₁/‖v₁‖"},
  {title:"3. Retirer la composante parallèle",body:"La projection de v₂ sur la droite engendrée par e₁ est ⟨v₂,e₁⟩e₁, car e₁ est unitaire. On retire cette composante pour obtenir un vecteur orthogonal à e₁.",formula:"proj_{e₁}(v₂)=⟨v₂,e₁⟩e₁ ; w₂=v₂−⟨v₂,e₁⟩e₁"},
  {title:"4. Vérification de l'orthogonalité",body:"Par bilinéarité du produit scalaire, ⟨w₂,e₁⟩=⟨v₂,e₁⟩−⟨v₂,e₁⟩⟨e₁,e₁⟩=0, puisque ‖e₁‖²=1. Le résidu est donc bien orthogonal au premier vecteur."},
  {title:"5. Normaliser le résidu",body:"Comme v₁ et v₂ sont indépendants, v₂ n'appartient pas à Vect(e₁), donc w₂≠0. On peut poser e₂=w₂/‖w₂‖. La famille (e₁,e₂) est orthonormée et engendre le même plan que (v₁,v₂).",formula:"e₂=w₂/‖w₂‖ ; ‖e₁‖=‖e₂‖=1 ; ⟨e₁,e₂⟩=0"},
  {title:"6. Exemple calculé",body:"Prenons v₁=(1,1), v₂=(1,0). Alors e₁=(1/√2,1/√2), puis ⟨v₂,e₁⟩=1/√2. Le projeté vaut (1/2,1/2), donc w₂=(1/2,−1/2). Sa norme vaut 1/√2, d'où e₂=(1/√2,−1/√2)."},
  {title:"7. Formule si l'on ne normalise pas v₁ au départ",body:"On peut aussi conserver u₁=v₁ et utiliser la formule générale de projection. Il faut alors diviser par le carré de la norme de v₁. Les deux méthodes sont équivalentes, mais il ne faut pas mélanger leurs notations.",formula:"proj_{v₁}(v₂)=[⟨v₂,v₁⟩/‖v₁‖²]v₁"}
 ],
 "suite-limite":[
  {title:"1. Lire la définition",body:"On fixe une précision ε>0, aussi petite soit-elle. Il faut ensuite trouver un rang N tel que tous les termes de rang n≥N soient à distance strictement inférieure à ε de ℓ. N dépend de ε, mais pas de n.",formula:"∀ε>0, ∃N∈ℕ, ∀n≥N, |uₙ−ℓ|<ε"},
  {title:"2. Méthode de preuve ε-N",body:"Partir de |uₙ−ℓ|<ε, isoler une condition suffisante sur n, choisir un entier N qui la garantit, puis reprendre n≥N arbitraire pour vérifier l'inégalité.",example:"Pour uₙ=3/(n+2), choisir N>3/ε suffit car n≥N entraîne 0≤uₙ≤3/(n+2)<ε."},
  {title:"3. Théorèmes utiles",body:"Une limite est unique ; toute suite convergente est bornée ; les opérations usuelles sur les limites sont compatibles avec somme, produit et quotient lorsque le dénominateur limite est non nul. Le théorème des gendarmes permet de conclure par encadrement.",formula:"uₙ≤vₙ≤wₙ et uₙ,wₙ→ℓ ⇒ vₙ→ℓ"},
  {title:"4. Erreurs classiques",body:"Ne pas confondre une condition nécessaire et une condition suffisante. En particulier uₙ→0 ne suffit pas à assurer la convergence de Σuₙ. Ne pas choisir N en fonction de n : il doit fonctionner pour tous les n assez grands."}
 ],
 "continuite":[
  {title:"1. Définition",body:"f est continue en a lorsque f(a) est définie et que les valeurs f(x) tendent vers f(a) quand x tend vers a. C'est une propriété locale.",formula:"lim(x→a)f(x)=f(a)"},
  {title:"2. Stabilité",body:"Somme, produit et composée de fonctions continues sont continus sur leur domaine. Un quotient est continu là où son dénominateur ne s'annule pas. Les polynômes sont continus sur ℝ."},
  {title:"3. Continuité et dérivabilité",body:"Dérivable en a implique continue en a, mais la réciproque est fausse. Exemple : |x| est continue en 0 mais n'y est pas dérivable, car les dérivées à gauche et à droite diffèrent."},
  {title:"4. Méthode",body:"Pour une fonction définie par morceaux, calculer séparément les limites à gauche et à droite, puis les comparer à la valeur au point. Pour une composition, vérifier la continuité des fonctions au bon point."}
 ],
 "derivee":[
  {title:"1. Définition et sens géométrique",body:"Le nombre dérivé est la limite du taux d'accroissement. Il représente la pente de la tangente à la courbe au point d'abscisse a.",formula:"f′(a)=lim(h→0)[f(a+h)−f(a)]/h"},
  {title:"2. Tangente",body:"La tangente au graphe au point (a,f(a)) a pour équation y=f(a)+f′(a)(x−a).",example:"Pour f(x)=x² en a=2, f(2)=4 et f′(2)=4 : y=4x−4."},
  {title:"3. Règles de calcul",body:"(u+v)′=u′+v′ ; (uv)′=u′v+uv′ ; (u/v)′=(u′v−uv′)/v² si v≠0 ; (g∘f)′=(g′∘f)f′."},
  {title:"4. Variations",body:"Si f′≥0 sur un intervalle, f est croissante ; si f′>0, elle est strictement croissante. Pour dresser un tableau de variations : domaine, dérivée, factorisation, signe, puis conclusion."}
 ],
 "espaces-vectoriels":[
  {title:"1. Critère de sous-espace",body:"Une partie F de E est un sous-espace si elle contient 0 et est stable par combinaison linéaire. Cette seule stabilité rassemble l'addition et la multiplication par les scalaires.",formula:"u,v∈F, λ,μ∈K ⇒ λu+μv∈F"},
  {title:"2. Reconnaître un noyau",body:"Si F est défini par une ou plusieurs équations linéaires homogènes, essayer de l'écrire comme noyau d'une application linéaire. Tout noyau est un sous-espace.",example:"F={(x,y,z):x−2y+z=0}=Ker(φ), où φ(x,y,z)=x−2y+z."},
  {title:"3. Somme et intersection",body:"L'intersection de deux sous-espaces est un sous-espace. La somme F+G est aussi un sous-espace et, en dimension finie, dim(F+G)=dim(F)+dim(G)−dim(F∩G)."},
  {title:"4. Pièges",body:"Une droite affine qui ne passe pas par l'origine n'est pas un sous-espace. Vérifier seulement l'addition est insuffisant : la stabilité par les scalaires est également nécessaire."}
 ],
 "familles-liberes":[
  {title:"1. Famille libre",body:"Une famille est libre si la seule combinaison linéaire nulle est la combinaison triviale. La méthode consiste à écrire λ₁e₁+⋯+λₚeₚ=0 et à résoudre le système.",formula:"λ₁e₁+⋯+λₚeₚ=0 ⇒ λ₁=⋯=λₚ=0"},
  {title:"2. Famille génératrice et base",body:"Une famille est génératrice si tout vecteur s'écrit comme combinaison de ses éléments. Une base est libre et génératrice ; les coordonnées de chaque vecteur dans une base sont alors uniques."},
  {title:"3. Critères dimensionnels",body:"Dans un espace de dimension n, une famille libre de n vecteurs est une base, tout comme une famille génératrice de n vecteurs. Plus de n vecteurs implique une famille liée."},
  {title:"4. Outil matriciel",body:"Dans ℝⁿ, placer les vecteurs en colonnes. Si la matrice carrée a un déterminant non nul, ses colonnes forment une base."}
 ],
 "applications-lineaires":[
  {title:"1. Définition",body:"Une application f:E→F est linéaire si elle préserve les combinaisons linéaires. Elle vérifie notamment f(0)=0.",formula:"f(λu+μv)=λf(u)+μf(v)"},
  {title:"2. Noyau et image",body:"Ker(f)={x∈E:f(x)=0} et Im(f)={f(x):x∈E}. Ce sont des sous-espaces. f est injective si et seulement si Ker(f)={0}."},
  {title:"3. Théorème du rang",body:"Si E est de dimension finie, dim(E)=dim(Ker(f))+rg(f). Pour une application entre espaces de même dimension finie, injectivité et surjectivité sont équivalentes."},
  {title:"4. Matrice",body:"Les colonnes de la matrice de f sont les coordonnées des images des vecteurs de la base de départ, exprimées dans la base d'arrivée."}
 ],
 "diagonalisation":[
  {title:"1. Définition",body:"A est diagonalisable s'il existe une base de vecteurs propres. Les colonnes de P sont ces vecteurs propres, dans le même ordre que les valeurs propres de D.",formula:"A=PDP⁻¹"},
  {title:"2. Méthode",body:"Calculer det(A−λI), trouver les valeurs propres, déterminer chaque noyau Ker(A−λI), puis réunir assez de vecteurs propres indépendants pour former une base."},
  {title:"3. Critère",body:"En dimension n, A est diagonalisable si la somme des dimensions des espaces propres vaut n. Avoir n valeurs propres distinctes est une condition suffisante, mais pas nécessaire."},
  {title:"4. Vérification",body:"Vérifier AP=PD permet de contrôler les vecteurs propres et leur ordre avant de conclure."}
 ],
 "integrale":[
  {title:"1. Intégrale algébrique",body:"Les contributions au-dessus de l'axe sont positives et celles en dessous sont négatives. L'intégrale n'est donc pas toujours une aire géométrique positive.",formula:"∫ₐᵇf(x)dx=F(b)−F(a), F′=f"},
  {title:"2. Propriétés",body:"Linéarité, relation de Chasles, positivité si f≥0, et comparaison si f≤g sur [a,b]."},
  {title:"3. Intégration par parties",body:"Elle vient de la dérivée d'un produit. Choisir u et v′ pour rendre l'intégrale restante plus simple.",formula:"∫ₐᵇuv′=[uv]ₐᵇ−∫ₐᵇu′v"},
  {title:"4. Changement de variable",body:"Avec x=φ(t), remplacer dx par φ′(t)dt et transformer aussi les bornes. Vérifier que la substitution est cohérente sur l'intervalle."}
 ],
 "integrales-generalisees":[
  {title:"1. Définition",body:"Une intégrale sur [a,+∞[ est la limite de ∫ₐᴮf quand B→+∞. Elle converge si la limite est finie. Pour une singularité, séparer les deux côtés.",formula:"∫ₐ^{+∞}f=lim(B→+∞)∫ₐᴮf"},
  {title:"2. Intégrales de Riemann",body:"Sur [1,+∞[, ∫1/xᵖ converge si et seulement si p>1. Sur ]0,1], elle converge si et seulement si p<1."},
  {title:"3. Méthode",body:"Repérer toutes les bornes problématiques, écrire les limites, calculer une primitive si possible et étudier chaque limite séparément."}
 ],
 "developpements-limites":[
  {title:"1. Définition",body:"Un DL est une approximation polynomiale locale avec un reste négligeable devant la dernière puissance conservée.",formula:"f(x)=a₀+a₁x+⋯+aₙxⁿ+o(xⁿ) quand x→0"},
  {title:"2. DL usuels",body:"eˣ=1+x+x²/2+x³/6+o(x³) ; sin x=x−x³/6+o(x³) ; cos x=1−x²/2+o(x²) ; ln(1+x)=x−x²/2+x³/3+o(x³)."},
  {title:"3. Utilisation",body:"Pour un équivalent, conserver le premier terme non nul. Lors d'un produit ou d'une composition, contrôler l'ordre du reste et ne garder que les puissances nécessaires."}
 ],
 "fourier":[
  {title:"1. Série réelle",body:"Pour une fonction 2π-périodique, on écrit une somme de cosinus et sinus. Le terme a₀/2 correspond à la moyenne sur une période.",formula:"f(x)∼a₀/2+Σₙ≥1(aₙcos(nx)+bₙsin(nx))"},
  {title:"2. Coefficients",body:"a₀=(1/π)∫₋π^πf(x)dx ; aₙ=(1/π)∫₋π^πf(x)cos(nx)dx ; bₙ=(1/π)∫₋π^πf(x)sin(nx)dx. Les symétries paire et impaire simplifient les calculs."},
  {title:"3. Convergence",body:"Sous des hypothèses classiques de régularité par morceaux, la série converge en x vers la demi-somme des limites latérales. Aux points de continuité, elle converge vers f(x)."}
 ]
};
for (const t of window.MATH_TOPICS) if (window.MATH_COURSE_DETAILS[t.id]) t.courseSections=window.MATH_COURSE_DETAILS[t.id];

window.MATH_CARDS = [
{cat:"Analyse",level:"L1",q:"Donner la définition de la convergence d'une suite.",a:"uₙ converge vers ℓ si : pour tout ε > 0, il existe N ∈ ℕ tel que pour tout n ≥ N, |uₙ − ℓ| < ε."},
{cat:"Analyse",level:"L1",q:"Dans la définition de convergence, de quoi dépend N ?",a:"N dépend de ε, mais ne dépend pas de n. Une fois N choisi, l'inégalité doit être vraie pour tout n ≥ N."},
{cat:"Analyse",level:"L1",q:"Quelle est la limite de 1/n lorsque n tend vers +∞ ?",a:"0. Pour tout ε > 0, choisir N > 1/ε suffit."},
{cat:"Analyse",level:"L1",q:"Énoncer le lien entre dérivabilité et continuité.",a:"Si f est dérivable en a, alors f est continue en a. La réciproque est fausse."},
{cat:"Analyse",level:"L1",q:"Définir le nombre dérivé de f en a.",a:"f′(a) = limₕ→₀ [f(a+h)−f(a)]/h, lorsque cette limite existe et est finie."},
{cat:"Analyse",level:"L1",q:"Que représente géométriquement f′(a) ?",a:"La pente de la tangente à la courbe représentative de f au point d'abscisse a."},
{cat:"Analyse",level:"L1",q:"Énoncer le théorème des valeurs intermédiaires.",a:"Si f est continue sur [a,b], elle prend toute valeur comprise entre f(a) et f(b)."},
{cat:"Analyse",level:"L1",q:"Une fonction continue strictement monotone sur un intervalle peut-elle avoir plusieurs fois la même valeur ?",a:"Non. La stricte monotonie assure l'injectivité, donc l'unicité d'un éventuel antécédent."},
{cat:"Analyse",level:"L1",q:"Quelle est une condition nécessaire de convergence d'une série ∑uₙ ?",a:"Il faut que uₙ tende vers 0. Attention : cette condition n'est pas suffisante."},
{cat:"Analyse",level:"L1",q:"Quand la série géométrique ∑qⁿ converge-t-elle ?",a:"Elle converge si et seulement si |q| < 1. Sa somme à partir de n=0 vaut 1/(1−q)."},
{cat:"Analyse",level:"L2",q:"Définir la convergence uniforme de fₙ vers f sur E.",a:"supₓ∈E |fₙ(x)−f(x)| tend vers 0. Dans la formulation ε-N, N ne dépend ni de x ni de n."},
{cat:"Analyse",level:"L2",q:"La convergence uniforme implique-t-elle la convergence simple ?",a:"Oui. Pour chaque x fixé, |fₙ(x)−f(x)| est majoré par le supremum qui tend vers 0."},
{cat:"Algèbre",level:"L1",q:"Comment montrer qu'une partie F est un sous-espace vectoriel ?",a:"Vérifier que F est non vide et que pour tous u,v∈F et λ,μ∈K, λu+μv appartient à F."},
{cat:"Algèbre",level:"L1",q:"Définir une famille libre.",a:"Une famille (e₁,…,eₚ) est libre si λ₁e₁+⋯+λₚeₚ=0 implique λ₁=⋯=λₚ=0."},
{cat:"Algèbre",level:"L1",q:"Définir une famille génératrice.",a:"Une famille est génératrice de E si tout vecteur de E peut s'écrire comme combinaison linéaire de ses éléments."},
{cat:"Algèbre",level:"L1",q:"Qu'est-ce qu'une base ?",a:"Une famille à la fois libre et génératrice."},
{cat:"Algèbre",level:"L1",q:"Quelle propriété caractérise une application linéaire ?",a:"Pour tous u,v et scalaires λ,μ : f(λu+μv)=λf(u)+μf(v)."},
{cat:"Algèbre",level:"L1",q:"Que vaut nécessairement f(0) pour une application linéaire ?",a:"f(0)=0. En effet f(0)=f(0+0)=f(0)+f(0)."},
{cat:"Algèbre",level:"L1",q:"Qu'est-ce que le noyau d'une application linéaire ?",a:"Ker(f)={x∈E | f(x)=0}. C'est un sous-espace vectoriel de E."},
{cat:"Algèbre",level:"L1",q:"Qu'est-ce que l'image d'une application linéaire ?",a:"Im(f)={f(x) | x∈E}. C'est un sous-espace vectoriel de F."},
{cat:"Algèbre",level:"L2",q:"Quelle équation caractéristique permet de trouver les valeurs propres d'une matrice carrée A ?",a:"det(A−λI)=0. Les solutions λ sont les valeurs propres."},
{cat:"Algèbre",level:"L2",q:"Que signifie diagonaliser une matrice A ?",a:"Trouver une matrice inversible P et une matrice diagonale D telles que A=PDP⁻¹."},
{cat:"Analyse",level:"MP",q:"Quel est le critère de compacité dans ℝⁿ ?",a:"Un ensemble de ℝⁿ est compact si et seulement s'il est fermé et borné."},
{cat:"Algèbre",level:"MP",q:"Que dit le théorème du rang ?",a:"Pour une application linéaire f:E→F avec E de dimension finie : dim(E)=dim(Ker f)+rg(f)."}
];


